  str_draw_card_freetentime_btn = "무료 10회 소집",
  str_draw_card_freeonetime_btn = "무료 1회 소집",
  str_draw_card_pool_detail_sub_desc1_1 = "본 소집은 <color=#ffbb00>신규 유저 전용으로</color>, 소집 가격은 일반 소집보다 저렴합니다. 소집 횟수는 <color=#ffbb00>21</color>회이며(튜토리얼 시 진행하는 첫 번째 소집 포함), 횟수가 소진되면 신규 유저 전용 소집은 종료됩니다.\n\n본 소집의 첫 <color=#ffbb00>11</color>회 동안 반드시 최소 1명의 5성 오로리안을 획득하며, 첫 20회 동안 6성 오로리안을 획득할 확률은 일반 소집을 참고하세요(하단 표시). 또한 첫 20회 소집 중 6성 오로리안의 획득 여부에 관계없이, <color=#ffbb00>21</color>번째 소집에서는 반드시 신규 유저 특별 엄선 6성 오로리안(<color=#ffbb00>나시리스/그로누/엘시/샤리</color> 중 임의의 1명)을 반드시 획득합니다.",
  str_draw_card_pool_detail_sub_desc1_2 = "등장 가능한 모든 오로리안\n『6성 오로리안』: 2.0%\n시로나/샤리/라파엘/코놀리/카론/엘시/빅토리아/요나/나시리스/가브리엘/미자드/미카엘/그로누/이리돈/레이스\n『5성 오로리안』: 9.5%\n와타리/바튼/클레이튼/필리시/노아/휴라드/베니&쿠로/레지나/파우스트/마지/이스타반/바바라/레오나/아이리나/펙트/스칼렛/루이스/오디/쿠스쿠타/디나/솔라드/네메시스/베벌리/키팅/비비안/미아\n『4성 오로리안』: 33.0%\n파솔로/제인/쿠마&페기/Ms. 블랑/미제니/크로이/콘스탄틴/파티&파시/봄버 존/앨리스/렉커/나일즈/찬드라/실바/레스터/유라/웬디/우라이아/테사/안시아/나딘/라비/리리암/카프카\n『3성 오로리안』: 55.5%\n세르고/조르아/나노스/코르곤/소크&베크/타이니/페피/톱날 리크/조무/클로버/오피나/도브/리아/안젤/유니메트/에호/에이미",
  str_draw_card_pool_detail_sub_desc1_3 = "어떠한 획득 방식(소집, 상점 교환, 시스템 선물 등 포함)으로든지 보유한 오로리안을 중복으로 획득하면 자원으로 전환됩니다.\n\n『6성 오로리안』 중복 획득 시 해당 오로리안의 솔람버 1개, 공용 하트스톤 200개, 트윙클젬 20개로 전환됩니다.\n첫 중복 획득 시 추가로 샤인젬 10개를 획득합니다.\n2회, 3회 중복 획득 시 추가로 샤인젬 20개를 획득합니다.\n4회 중복 획득 시 추가로 샤인젬 30개를 획득합니다. 5회 이상 중복 획득 시 추가로 샤인젬 50개를 획득합니다.\n\n『5성 오로리안』 중복 획득 시 해당 오로리안의 솔람버 1개, 공용 하트스톤 100개, 트윙클젬 5개로 전환됩니다.\n1회, 2회 중복 획득 시 추가로 샤인젬 1개를 획득합니다.\n3회, 4회 중복 획득 시 추가로 샤인젬 2개를 획득합니다.\n5회 이상 중복 획득 시 추가로 샤인젬 3개를 획득합니다.\n\n『4성 오로리안』 중복 획득 시 해당 오로리안의 솔람버 1개, 공용 하트스톤 50개, 스타젬 25개로 전환됩니다.\n\n『3성 오로리안』 중복 획득 시 공용 하트스톤 50개, 스타젬 10개로 전환됩니다.",
  str_draw_card_pool_name_10001 = "통용 표준 소집",
  str_draw_card_pool_des_10001 = "첫 10회 소집 시 반드시 5성 오로리안 1명 획득",
  str_draw_card_pool_title_10001_1 = "통용 표준 소집",
  str_draw_card_pool_title_10001_2 = "이상의 오로리안 외 다수의 6성 오로리안 포함",
  str_draw_card_pool_detail_title_10001 = "통용 표준 소집 설명",
  str_draw_card_pool_detail_sub_desc10001_1 = "본 통용 표준 소집은 <color=#ffbb00>영구 개방되며</color>, 스타 마커를 사용해 소집합니다.\n\n6성 오로리안을 획득할 초기 확률은 <color=#ffbb00>2%</color>이며, 연속 <color=#ffbb00>50</color>회까지 6성 오로리안을 획득하지 못했다면, 다음번 소집에서 6성 오로리안을 획득할 확률은 기존의 <color=#ffbb00>2%</color>에서 <color=#ffbb00>4.5%</color>로 증가합니다. 만약 다음 소집에서도 여전히 6성 오로리안을 획득하지 못했다면 그 다음번 소집에서 6성 오로리안을 획득할 확률은 기존의 <color=#ffbb00>4.5%</color>에서 <color=#ffbb00>7%</color>로 증가합니다. 이러한 방식으로 매회 <color=#ffbb00>2.5%</color>씩 6성 오로리안을 획득할 확률이 증가하며, <color=#ffbb00>100%</color>가 되면 <color=#ffbb00>반드시</color> 6성 오로리안을 획득합니다. 6성 오로리안을 획득한 후 해당 확률 증가 효과는 초기화되며, 6성 오로리안 획득 확률은 <color=#ffbb00>2%</color>가 됩니다.\n\n주의: 통용 표준 소집에서 획득하는 6성 확률 상승은 한정 소집 확률과 별개이며, 서로 영향을 받지 않습니다. 즉, 통용 표준 소집에서 6성 획득 확률이 <color=#ffbb00>7%</color>로 증가하더라도 다른 한정 소집에는 영향을 주지 않으며, 반대의 경우에도 동일합니다.",
  str_draw_card_pool_detail_sub_desc10001_2 = "<color=#ffbb00>모든 오로리안 등장 확률: </color>\n『6성 오로리안』: 2.0%\n『5성 오로리안』: 9.5%\n『4성 오로리안』: 33.0%\n『3성 오로리안』: 55.5%",
