  str_draw_card_pool_name_21001 = "레디젤 리더 한정 소집",
  str_draw_card_pool_title_21001_1 = "[레디젤 리더]",
  str_draw_card_pool_title_21001_2 = "[사메야마] 이벤트 기간 확률 UP",
  str_draw_card_pool_detail_title_21001 = "[레디젤 리더] 한정 소집 설명",
  str_draw_card_pool_detail_sub_desc21001_1 = "한정 소집은 주기적으로 개방되며, 특별 소집 스타 마커를 사용해 소집합니다. 한정 소집이 업데이트되면 첫 10회 소집에는 반드시 5성 오로리안을 1명 획득합니다.\n\n6성 오로리안을 획득할 초기 확률은 2%이며, 연속 50회까지 6성 오로리안을 획득하지 못했다면, 다음번 소집에서 6성 오로리안을 획득할 확률은 기존의 2%에서 4.5%로 증가합니다. 만약 다음 소집에서도 여전히 6성 오로리안을 획득하지 못했다면 그 다음번 소집에서 6성 오로리안을 획득할 확률은 기존의 4.5%에서 7%로 증가합니다. 이러한 방식으로 매회 2.5%씩 6성 오로리안을 획득할 확률이 증가하며, 100%가 되면 반드시 6성 오로리안을 획득합니다. 6성 오로리안을 획득한 후 해당 확률 증가 효과는 초기화되며, 6성 오로리안 획득 확률은 2%가 됩니다.\n\n모든 한정 소집에서 6성 오로리안을 획득하지 못했다면, 해당 횟수는 모두 누적됩니다. 즉, 모든 한정 소집은 공통으로 상술한 규칙에 따라 확률이 상승합니다. 해당 횟수는 특정 한정 소집이 종료되더라도 초기화되지 않으며, 다음 한정 소집으로 이어집니다. 또한 만약 동시에 여러 종류의 한정 소집이 개방되었다면, 그중 어떤 한정 소집을 진행하더라도 횟수는 모두 함께 누적됩니다.\n\n임의의 한정 소집에서 6성 오로리안을 획득할 경우 해당 확률 증가 효과는 초기화되며, 6성 오로리안 획득 확률은 2%가 됩니다. 또한 한정 소집에서 획득하는 6성 확률 상승은 통용 표준 소집 확률과 별개이며, 서로 영향을 받지 않습니다.",
  str_draw_card_pool_detail_sub_desc21001_2 = "[레디젤 리더] 한정 소집 중, 다음 오로리안의 등장 확률이 증가함\n사메야마: 6성 오로리안 등장 확률의 50% 점유\n\n등장 가능한 모든 오로리안\n『6성 오로리안』: 2.0%\n사메야마/히이로/시로나/샤리/라파엘/코놀리/카론/엘시/빅토리아/요나/나시리스/가브리엘/미자드/미카엘/그로누/이리돈/레이스\n『5성 오로리안』: 9.5%\n타키/와타리/바튼/클레이튼/필리시/노아/휴라드/베니&쿠로/레지나/파우스트/마지/이스타반/바바라/레오나/아이리나/펙트/스칼렛/루이스/오디/쿠스쿠타/디나/솔라드/네메시스/베벌리/키팅/비비안/미아\n『4성 오로리안』: 33.0%\n제인/쿠마&페기/Ms. 블랑/미제니/크로이/콘스탄틴/파티&파시/봄버 존/앨리스/렉커/나일즈/찬드라/실바/레스터/유라/웬디/우라이아/테사/안시아/나딘/라비/리리암/카프카\n『3성 오로리안』: 55.5%\n세르고/조르아/나노스/코르곤/소크&베크/타이니/페피/톱날 리크/조무/클로버/오피나/도브/리아/안젤/유니메트/에호/에이미",
