  str_draw_card_pool_title_40010_2 = "10회 소집 시 반드시 지정 6성 오로리안 중 1명 획득",
  str_draw_card_pool_title_40010_1 = "겨울의 송가 특전 소집",
  str_draw_card_pool_des_40010 = "10회 소집 후 겨울의 송가 특전 소집은 종료됨",
  str_draw_card_pool_detail_title_40010 = "겨울의 송가 특전 소집 설명",
  str_draw_card_pool_detail_sub_desc40010_1 = "본 소집은 겨울의 송가 특전 소집으로, 상점에서 지정 아이템인 [송가 10연속 특전 소집령]을 구매해야만 참가할 수 있습니다. 지정 아이템인 [송가 10연속 특전 소집령]은 10연속 소집을 1회 진행할 수 있는 아이템으로, 사용 후 겨울의 송가 특전 소집은 종료됩니다.\n\n본 소집을 진행하면 지정 6성 오로리안(<color=#ffbb00>로렐라이/조슈아/잉겔/솔라드 디 올마이티 클레머</color> 중 랜덤) 1명을 반드시 획득합니다. 나머지 9회의 소집은 통용 표준 소집의 확률에 따라 소집을 진행하므로, 6성 오로리안을 추가로 획득할 수도 있습니다. 자세한 확률 및 목록은 하단의 내용을 참고해 주시기 바랍니다.\n\n※특별 설명: 겨울의 송가 특전 소집은 한정 소집으로, 기간 내에만 소집을 진행할 수 있습니다.\n\n지정 아이템인 [송가 10연속 특전 소집령]을 구매하셨으나, 이번 소집에 참가하지 못하신 경우, [송가 10연속 특전 소집령] 아이템은 겨울의 송가 특전 소집 종료 후 3000루맘버로 전환되어 우편으로 지급됩니다.",
  str_draw_card_pool_name_50001 = "지정 소집 [물]",
  str_draw_card_pool_des_50001 = "첫 10회 소집 시 반드시 5성 물 속성 오로리안 1명 획득",
  str_draw_card_pool_title_50001_1 = "지정 소집 [물]",
  str_draw_card_pool_title_50001_2 = "본 소집에서는 [물] 속성 오로리안만 소집 가능",
  str_draw_card_pool_detail_title_50001 = "지정 소집 [물] 설명",
  str_draw_card_pool_detail_sub_desc50001_1 = "지정 소집은 총 4종류로 구성되어 있으며, 각 속성에 대응하는 한정 개방 특별 소집입니다. 본 소집은 <color=#ffbb00>물 속성의 지정 소집으로, 본 소집에서는 물 속성의 오로리안만 획득할 수 있습니다</color>. 스타 마커를 사용해 소집을 진행하며, 첫 10회 소집에는 반드시 5성 <color=#ffbb00>물 속성 오로리안</color>을 1명 획득합니다.\n\n각 성급의 오로리안을 획득할 확률은 통용 소집과 동일하며, 자세한 사항은 오로리안 획득 확률 설명을 참고해 주시기 바랍니다.\n\n6성 오로리안을 획득할 초기 확률은 2%이며, 연속 50회까지 6성 오로리안을 획득하지 못했다면, 다음번 소집에서 6성 오로리안을 획득할 확률은 기존의 2%에서 4.5%로 증가합니다. 만약 다음 소집에서도 여전히 6성 오로리안을 획득하지 못했다면 그 다음번 소집에서 6성 오로리안을 획득할 확률은 기존의 4.5%에서 7%로 증가합니다. 이러한 방식으로 매회 2.5%씩 6성 오로리안을 획득할 확률이 증가하며, 100%가 되면 반드시 6성 오로리안을 획득합니다. 6성 오로리안을 획득한 후 해당 확률 증가 효과는 초기화되며, 6성 오로리안 획득 확률은 2%가 됩니다.\n\n모든 4속성 지정 소집에서 6성 오로리안을 획득하지 못했다면, 해당 횟수는 모두 누적되며, 서로 공유됩니다. 즉, 모든 4속성 지정 소집은 공통으로 상술한 규칙에 따라 확률이 상승합니다. 지정 소집의 6성 확률 증가는 같은 기간의 나머지 소집의 확률과 별개이며, 서로 영향을 받지 않습니다. 또한 향후 어떠한 소집으로도 이어지지 않습니다.",
  str_draw_card_pool_detail_sub_desc50001_2 = "등장 가능한 모든 오로리안\n『6성 오로리안』: 2.0%\n플뢰르/카렌/시로나/샤리/라파엘/코놀리\n『5성 오로리안』: 9.5%\n와타리/바튼/클레이튼/필리시/노아/휴라드\n『4성 오로리안』: 33.0%\n트위티/제인/쿠마&페기/Ms. 블랑/미제니/크로이/콘스탄틴\n『3성 오로리안』: 55.5%\n세르고/조르아/나노스/코르곤",
  str_draw_card_pool_detail_sub_desc50005_1 = "지정 소집은 총 4종류로 구성되어 있으며, 각 속성에 대응하는 한정 개방 특별 소집입니다. 본 소집은 <color=#ffbb00>물 속성의 지정 소집으로, 본 소집에서는 물 속성의 오로리안만 획득할 수 있습니다</color>. 스타 마커를 사용해 소집을 진행하며, 첫 10회 소집에는 반드시 5성 <color=#ffbb00>물 속성 오로리안</color>을 1명 획득합니다.\n\n각 성급의 오로리안을 획득할 확률은 통용 소집과 동일하며, 자세한 사항은 오로리안 획득 확률 설명을 참고해 주시기 바랍니다.\n\n6성 오로리안을 획득할 초기 확률은 <color=#ffbb00>2%</color>이며, 연속 <color=#ffbb00>50</color>회까지 6성 오로리안을 획득하지 못했다면, 다음번 소집에서 6성 오로리안을 획득할 확률은 기존의 <color=#ffbb00>2%</color>에서 <color=#ffbb00>4.5%</color>로 증가합니다. 만약 다음 소집에서도 여전히 6성 오로리안을 획득하지 못했다면 그 다음번 소집에서 6성 오로리안을 획득할 확률은 기존의 <color=#ffbb00>4.5%</color>에서 <color=#ffbb00>7%</color>로 증가합니다. 이러한 방식으로 매회 <color=#ffbb00>2.5%</color>씩 6성 오로리안을 획득할 확률이 증가하며, <color=#ffbb00>100%</color>가 되면 <color=#ffbb00>반드시</color> 6성 오로리안을 획득합니다. 6성 오로리안을 획득한 후 해당 확률 증가 효과는 초기화되며, 6성 오로리안 획득 확률은 <color=#ffbb00>2%</color>가 됩니다.\n\n모든 4속성 지정 소집에서 6성 오로리안을 획득하지 못했다면, 해당 횟수는 모두 누적되며, 서로 공유됩니다. 즉, 모든 4속성 지정 소집은 공통으로 상술한 규칙에 따라 확률이 상승합니다. 지정 소집의 6성 확률 증가는 같은 기간의 나머지 소집의 확률과 별개이며, 서로 영향을 받지 않습니다. 또한 향후 어떠한 소집으로도 이어지지 않습니다.",
  str_draw_card_pool_detail_sub_desc50005_2 = "등장 가능한 모든 오로리안\n『6성 오로리안』: 2.0%\n루비/베델/플뢰르/카렌/시로나/샤리/라파엘/코놀리\n『5성 오로리안』: 9.5%\n와타리/바튼/클레이튼/필리시/노아/휴라드\n『4성 오로리안』: 33.0%\n트위티/제인/쿠마&페기/Ms. 블랑/미제니/크로이/콘스탄틴\n『3성 오로리안』: 55.5%\n세르고/조르아/나노스/코르곤",
