  str_draw_card_pool_detail_sub_desc90002_2 = "오로리안 등장 확률 설명\n『6성 오로리안』: 2.0%\n『5성 오로리안』: 9.5%\n『4성 오로리안』: 33.0%\n『3성 오로리안』: 55.5%",
  str_draw_card_pool_name_60008 = "황혼의 교향시 특별 한정 소집",
